def canta():
    """Cântă sunetul și așteaptă să se termine (programul se închide după). Întoarce False dacă nu se poate."""
    if os.name != 'nt':
        return False
    try:
        import winsound
        d = os.path.join(tempfile.gettempdir(), 'RegatulPartiturilor')
        os.makedirs(d, exist_ok=True)
        cale = os.path.join(d, 'iesire-celesta.wav')
        date = base64.b64decode(_WAV)
        if not os.path.isfile(cale) or os.path.getsize(cale) != len(date):
            with open(cale, 'wb') as f:
                f.write(date)
        winsound.PlaySound(cale, winsound.SND_FILENAME | winsound.SND_NODEFAULT)
        return True
    except Exception:
        return False
